    return {enabled:value.enabled!==false,blur:n('blur',24,50),grain:n('grain',44,100),tone:n('tone',90,100),wash:n('wash',58,100),color:/^#[0-9a-f]{6}$/i.test(value.color||'')?value.color:'#2936ff'};
