/* Source: scripts/ticket-paper-texture-asset.js */
/* Exact preview paper texture, embedded for origin-safe local PNG export. */
window.LOG_TICKET_PAPER_TEXTURE_ASSET="data:image/png;base64,";
// Keep the large paper image out of CSS custom-property token limits.
// The PNG bytes stay embedded above; the object URL exists only in this page.
(function () {
  var encoded = window.LOG_TICKET_PAPER_TEXTURE_ASSET.split(",")[1];
  var decoded = atob(encoded);
  var bytes = new Uint8Array(decoded.length);
  for (var index = 0; index < decoded.length; index += 1) bytes[index] = decoded.charCodeAt(index);
  var textureUrl = URL.createObjectURL(new Blob([bytes], { type: "image/png" }));
  document.documentElement.style.setProperty("--log-ticket-paper-texture", 'url("' + textureUrl + '")');
})();

